    while (continueManaging) {
        const resources = await fetchResourcesCore(context);
        displayResourcesCore(resources);
        const actionAnswer = await safePrompt([
            {
                type: 'list',
                name: 'action',
                message: 'What would you like to do?',
                choices: [
                    { name: '➕ Create new resource', value: 'create' },
                    { name: '✏️  Update existing resource', value: 'update' },
                    { name: '🗑️  Delete resource', value: 'delete' },
                    { name: '👁️  View resource content', value: 'view' },
                    { name: '🔄 Refresh list', value: 'refresh' },
                    { name: '❌ Exit', value: 'exit' }
                ]
            }
        ]);
        if (!actionAnswer)
            return;
        const { action } = actionAnswer;
        switch (action) {
            case 'create':
                await createResourceInteractive(context);
                break;
            case 'update':
                await updateResourceInteractive(context, resources);
                break;
            case 'delete':
                await deleteResourceInteractive(context, resources);
                break;
            case 'view':
                await viewResourceInteractive(resources);
                break;
            case 'refresh':
                break;
            case 'exit':
                continueManaging = false;
                console.log("\n👋 Goodbye!\n");
                break;
        }
    }
